import{_ as a,o,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Lista de Sugestões de Expansão de Configurações","description":"","frontmatter":{},"headers":[],"relativePath":"pt/98-扩展设定建议清单.md","filePath":"pt/98-扩展设定建议清单.md","lastUpdated":null}'),s={name:"pt/98-扩展设定建议清单.md"};function i(r,e,n,c,u,m){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="lista-de-sugestoes-de-expansao-de-configuracoes" tabindex="-1">Lista de Sugestões de Expansão de Configurações <a class="header-anchor" href="#lista-de-sugestoes-de-expansao-de-configuracoes" aria-label="Permalink to &quot;Lista de Sugestões de Expansão de Configurações&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>98</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave principais</td><td>expansão de configurações, sugestões criativas, direções de configuração, abertura, áreas a desenvolver</td></tr></tbody></table><h2 id="_1-descricao" tabindex="-1">1. Descrição <a class="header-anchor" href="#_1-descricao" aria-label="Permalink to &quot;1. Descrição&quot;">​</a></h2><p>Este documento lista as direções e sugestões disponíveis para criação expansiva no sistema de configurações da Civilização de Simbiose de Âncora, com o objetivo de fornecer inspiração e orientação aos criadores de configurações, ajudando-os a realizar expansões valiosas de configurações dentro da estrutura existente. Esta lista é classificada por módulos, e cada direção de expansão inclui descrição da direção, valor da expansão, relação com configurações existentes e sugestões criativas. É importante enfatizar que esta lista é apenas uma referência sugestiva; os criadores podem atuar livremente sob a premissa de seguir a consistência das configurações, ou podem desenvolver direções completamente novas não cobertas por esta lista. Todas as configurações expansivas devem passar pela verificação do Documento 97 &quot;Tabela de Autoverificação de Contradições de Configurações&quot; antes de serem oficialmente incorporadas.</p><h2 id="_2-direcoes-de-expansao-da-visao-de-mundo-e-configuracoes-centrais" tabindex="-1">2. Direções de Expansão da Visão de Mundo e Configurações Centrais <a class="header-anchor" href="#_2-direcoes-de-expansao-da-visao-de-mundo-e-configuracoes-centrais" aria-label="Permalink to &quot;2. Direções de Expansão da Visão de Mundo e Configurações Centrais&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E01</td><td>Existência além dos limites do universo</td><td>Explorar se existem outros universos ou seres de dimensões superiores fora da rede de leis de Hengyuanzhou, fornecendo uma visão de universo mais grandiosa para as configurações</td><td>Documento 00, Documento 28</td><td>Pode-se configurar a existência da &quot;parede do universo&quot; e as histórias de poucos exploradores que romperam a parede do universo, deixando pistas para futuras interações entre universos</td></tr><tr><td>E02</td><td>Essência da vontade do universo</td><td>Discutir profundamente se existe alguma &quot;vontade do universo&quot; na camada inferior da rede de leis e sua relação com o mecanismo de âncora</td><td>Documento 00, Documento 20</td><td>Pode-se configurar a vontade do universo como um fenômeno de auto-organização de leis impessoal, em vez de uma divindade específica, mantendo a posição de &quot;baseado na realidade&quot;</td></tr><tr><td>E03</td><td>Civilizações perdidas da era pré-âncora</td><td>Configurar detalhadamente civilizações que já foram prósperas mas desapareceram na era pré-âncora, enriquecendo a profundidade histórica</td><td>Documento 71, Documento 93</td><td>Pode-se configurar 3-5 civilizações perdidas representativas, cada uma com seu próprio sistema de cultivo único, cultura e razões de desaparecimento, fornecendo material para configurações arqueológicas</td></tr><tr><td>E04</td><td>Escolas filosóficas do conceito de simbiose</td><td>Sob a grande estrutura de &quot;anti-saque, advogar simbiose&quot;, configurar diferentes interpretações de diferentes escolas filosóficas sobre o conceito de simbiose</td><td>Documento 04, Documento 03</td><td>Pode-se configurar escolas como &quot;escola radical de simbiose&quot;, &quot;escola moderada de simbiose&quot;, &quot;escola ecológica de simbiose&quot;, &quot;escola tecnológica de simbiose&quot;, e o confronto ideológico entre elas pode se tornar uma importante tensão de enredo</td></tr></tbody></table><h2 id="_3-direcoes-de-expansao-do-sistema-de-cultivo" tabindex="-1">3. Direções de Expansão do Sistema de Cultivo <a class="header-anchor" href="#_3-direcoes-de-expansao-do-sistema-de-cultivo" aria-label="Permalink to &quot;3. Direções de Expansão do Sistema de Cultivo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E05</td><td>Métodos detalhados de um único sistema</td><td>Expandir detalhadamente um dos trezentos sistemas, incluindo métodos específicos de cultivo, métodos de rompimento de reinos, equívocos comuns, etc.</td><td>Documento 10-19, Documento 91</td><td>Recomenda-se priorizar a expansão das três bases fundamentais e dos sistemas da categoria de engenharia aplicada que estão intimamente ligados à tecnologia; o documento detalhado de cada sistema pode incluir etapas de cultivo, fórmulas mentais, requisitos de recursos, avisos de risco, etc.</td></tr><tr><td>E06</td><td>Planos de combinação de cultivo simultâneo de sistemas</td><td>Pesquisar a compatibilidade de cultivo simultâneo entre diferentes sistemas e projetar planos ótimos de combinação de múltiplos sistemas</td><td>Documento 10, Documento 11-13</td><td>Pode-se configurar &quot;combinações douradas&quot; (como iteração de dedução + leis espaciais + engenharia aplicada) e várias combinações incomuns, analisando as vantagens e limitações de cada combinação</td></tr><tr><td>E07</td><td>Gargalos de cultivo e métodos de rompimento</td><td>Configurar detalhadamente os gargalos que cada sistema pode encontrar em diferentes reinos e vários métodos de rompimento de gargalos</td><td>Documento 14, Documento 19</td><td>Pode-se configurar diferentes tipos de gargalos como &quot;tribulação do demônio interior&quot;, &quot;barreira das leis&quot;, &quot;obstrução da origem&quot;, e os caminhos de rompimento correspondentes, aumentando a hierarquia do processo de cultivo</td></tr><tr><td>E08</td><td>Constituições especiais e adaptação de sistemas</td><td>Configurar várias constituições especiais (como constituição dao inata, corpo de afinidade elemental, corpo de sensibilidade consciente, etc.) e suas relações de adaptação com diferentes sistemas de cultivo</td><td>Documento 12, Documento 51</td><td>Pode-se projetar uma &quot;matriz de adaptação constituição-sistema&quot; para ajudar os criadores a julgar rapidamente quais sistemas são adequados para uma determinada constituição</td></tr><tr><td>E09</td><td>Classificação detalhada de recursos de cultivo</td><td>Classificar e configurar detalhadamente vários recursos necessários para o cultivo (tesouros naturais, cristais de energia, fragmentos de leis, etc.)</td><td>Documento 18, Documento 65</td><td>Pode-se configurar o grau, local de produção, método de coleta, método de preservação, tabus de uso dos recursos, etc., construindo um ecossistema completo de recursos de cultivo</td></tr></tbody></table><h2 id="_4-direcoes-de-expansao-do-sistema-social" tabindex="-1">4. Direções de Expansão do Sistema Social <a class="header-anchor" href="#_4-direcoes-de-expansao-do-sistema-social" aria-label="Permalink to &quot;4. Direções de Expansão do Sistema Social&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E10</td><td>Formas sociais específicas dos cinco tipos</td><td>Expandir detalhadamente os sistemas sociais específicos, modelos econômicos e características culturais de cada um dos cinco tipos de civilização de simbiose</td><td>Documento 30-35</td><td>Cada tipo pode configurar sua forma urbana típica, estrutura familiar, modelo educacional, celebrações de festivais, etc., tornando os cinco tipos distintos</td></tr><tr><td>E11</td><td>Planejamento e construção de cidades de simbiose</td><td>Configurar o conceito de planejamento, estilo arquitetônico, infraestrutura e zoneamento funcional das cidades na civilização de simbiose</td><td>Documento 39, Documento 60</td><td>Pode-se projetar diferentes tipos de formas urbanas como &quot;cidades verticais de simbiose&quot;, &quot;cidades aninhadas ecológicas&quot;, &quot;cidades de dobra espacial&quot;</td></tr><tr><td>E12</td><td>Operação detalhada do sistema educacional</td><td>Configurar detalhadamente o mecanismo completo de operação do sistema educacional de simbiose, desde a educação pré-escolar até o ensino superior e a educação de cultivo</td><td>Documento 37, Documento 43</td><td>Pode-se configurar o sistema curricular, métodos de avaliação, sistema de mentores, planos de educação inter-racial, etc.</td></tr><tr><td>E13</td><td>Operação detalhada do sistema médico</td><td>Configurar detalhadamente o mecanismo de operação do sistema médico de simbiose, incluindo a combinação de medicina convencional e medicina de cultivo</td><td>Documento 38, Documento 44</td><td>Pode-se configurar o sistema hospitalar, processo de reembolso de seguro médico, normas especiais de tratamento de cultivo, planos de medicina inter-racial, etc.</td></tr><tr><td>E14</td><td>Seguridade social e sistema de bem-estar</td><td>Configurar detalhadamente o sistema de seguridade social da civilização de simbiose, incluindo aposentadoria, desemprego, assistência, etc.</td><td>Documento 32, Documento 08</td><td>Pode-se configurar as condições de solicitação de bem-estar, padrões de distribuição, fontes de financiamento, mecanismos de supervisão, etc.</td></tr></tbody></table><h2 id="_5-direcoes-de-expansao-legal-e-de-governanca" tabindex="-1">5. Direções de Expansão Legal e de Governança <a class="header-anchor" href="#_5-direcoes-de-expansao-legal-e-de-governanca" aria-label="Permalink to &quot;5. Direções de Expansão Legal e de Governança&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E15</td><td>Casos jurídicos típicos</td><td>Escrever casos típicos julgados pelo Tribunal de Simbiose, mostrando a aplicação prática da lei</td><td>Documento 40-49, Documento 92</td><td>Pode-se escrever casos representativos como &quot;caso de monopólio de recursos de cultivo&quot;, &quot;caso de indenização por poluição inter-planar&quot;, &quot;caso de direitos de corpo de substituição sombrio&quot;</td></tr><tr><td>E16</td><td>Sistema de autonomia local</td><td>Configurar detalhadamente o sistema de autonomia e divisão de poderes de cada região estelar e cada plano dentro da estrutura constitucional</td><td>Documento 40, Documento 49</td><td>Pode-se configurar os modelos de autonomia de diferentes unidades autônomas, relações com o governo central, processos de formulação de regulamentos de autonomia, etc.</td></tr><tr><td>E17</td><td>Sistema eleitoral e democrático</td><td>Configurar detalhadamente o sistema eleitoral dos representantes do Conselho de Âncora e o mecanismo de tomada de decisão democrática</td><td>Documento 32, Documento 49</td><td>Pode-se configurar a divisão de distritos eleitorais, qualificação de candidatos, processo eleitoral, método de votação, sistema de mandatos, etc.</td></tr><tr><td>E18</td><td>Mecanismo de execução legal</td><td>Configurar detalhadamente o mecanismo de execução da lei, incluindo agências de execução, processos de execução, medidas coercitivas</td><td>Documento 48, Documento 49</td><td>Pode-se configurar a estrutura organizacional das agências de execução, poderes de execução, processos de execução, mecanismos de supervisão, etc.</td></tr></tbody></table><h2 id="_6-direcoes-de-expansao-de-vida-e-racas" tabindex="-1">6. Direções de Expansão de Vida e Raças <a class="header-anchor" href="#_6-direcoes-de-expansao-de-vida-e-racas" aria-label="Permalink to &quot;6. Direções de Expansão de Vida e Raças&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E19</td><td>Configuração detalhada de uma única raça</td><td>Expandir detalhadamente uma raça do Catálogo de Todas as Raças, incluindo características fisiológicas, estrutura social, tradições culturais, evolução histórica</td><td>Documento 50-52, Documento 94</td><td>Recomenda-se priorizar a expansão de raças características como raça dragão, raça élfica, raça mecânica, raça de seres conscientes; cada raça pode incluir idioma, religião, arte, costumes, etc.</td></tr><tr><td>E20</td><td>Casos específicos de vida estranha</td><td>Configurar indivíduos ou grupos específicos de vida estranha, mostrando a aplicação prática dos três tipos de processos de tratamento</td><td>Documento 53-54</td><td>Pode-se configurar casos de vida estranha como &quot;derivantes do vazio&quot;, &quot;vida de fragmentos temporais&quot;, &quot;parasitas de leis&quot;</td></tr><tr><td>E21</td><td>Tipos específicos de energia estranha</td><td>Configurar detalhadamente as características, fontes, usos e métodos de controle de várias energias estranhas</td><td>Documento 55-56</td><td>Pode-se configurar tipos de energia estranha como &quot;energia causal&quot;, &quot;energia consciente&quot;, &quot;energia de ressonância temporal&quot;</td></tr><tr><td>E22</td><td>Casos específicos de corpos de substituição sombrio</td><td>Configurar histórias individuais específicas de corpos de substituição sombrio, mostrando a aplicação prática da ética de almas duplas e dos quatro tipos de tratamento de ramos</td><td>Documento 57-59</td><td>Pode-se escrever histórias de casos de diferentes tipos de corpos de substituição sombrio, explorando o dilema ético da coexistência de almas duplas</td></tr><tr><td>E23</td><td>Descendentes de fusão inter-racial</td><td>Configurar as características e culturas de raças mistas resultantes do casamento entre diferentes raças</td><td>Documento 52, Documento 77</td><td>Pode-se configurar raças mistas como &quot;meio-élfico&quot;, &quot;homem-dragão&quot;, &quot;biomecânico&quot;, explorando sua identidade e fusão cultural</td></tr></tbody></table><h2 id="_7-direcoes-de-expansao-tecnologica-e-de-energia" tabindex="-1">7. Direções de Expansão Tecnológica e de Energia <a class="header-anchor" href="#_7-direcoes-de-expansao-tecnologica-e-de-energia" aria-label="Permalink to &quot;7. Direções de Expansão Tecnológica e de Energia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E24</td><td>Princípios detalhados de uma única tecnologia</td><td>Analisar detalhadamente os princípios de uma tecnologia chave (como espelho de cópia, espaço isolado, engenharia da fruta Bei Zeng)</td><td>Documento 60-69, Documento 63-64</td><td>Pode-se configurar o histórico de desenvolvimento da tecnologia, componentes centrais, fluxo de trabalho, limitações tecnológicas, direções de atualização, etc.</td></tr><tr><td>E25</td><td>Classificação detalhada de instrumentos de cultivo</td><td>Configurar a classificação, funções, graus e métodos de uso de vários instrumentos auxiliares de cultivo</td><td>Documento 61, Documento 67</td><td>Pode-se configurar tipos de instrumentos como &quot;cápsula de cultivo&quot;, &quot;detector de leis&quot;, &quot;conversor de energia&quot;, &quot;amplificador consciente&quot;</td></tr><tr><td>E26</td><td>Configuração detalhada de hardware de âncora</td><td>Configurar detalhadamente a estrutura, funções, construção e manutenção das instalações de hardware de âncora</td><td>Documento 20, Documento 67</td><td>Pode-se configurar os componentes centrais de âncoras artificiais, fornecimento de energia, ciclo de manutenção, tratamento de falhas, etc.</td></tr><tr><td>E27</td><td>Tecnologia de comunicação inter-planar</td><td>Configurar detalhadamente os princípios tecnológicos, tipos de dispositivos, protocolos de comunicação e mecanismos de segurança da comunicação inter-planar</td><td>Documento 66, Documento 81</td><td>Pode-se configurar diferentes métodos de comunicação como &quot;comunicação de onda de âncora&quot;, &quot;comunicação de dobra espacial&quot;, &quot;comunicação de ressonância consciente&quot;</td></tr></tbody></table><h2 id="_8-direcoes-de-expansao-historica-e-de-eventos" tabindex="-1">8. Direções de Expansão Histórica e de Eventos <a class="header-anchor" href="#_8-direcoes-de-expansao-historica-e-de-eventos" aria-label="Permalink to &quot;8. Direções de Expansão Histórica e de Eventos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E28</td><td>Narrativa detalhada de eventos históricos importantes</td><td>Narrativa histórica detalhada de um evento importante na crônica</td><td>Documento 70-79, Documento 93</td><td>Pode-se narrar detalhadamente todo o processo de eventos como &quot;evento de abertura dos trezentos sistemas&quot;, &quot;implementação da estratégia de ativação de 20%&quot;, &quot;marco da primeira elevação de dimensão&quot;</td></tr><tr><td>E29</td><td>Biografias de personagens históricos</td><td>Escrever biografias detalhadas para personagens chave, enriquecendo a profundidade humana da história</td><td>Documento 95</td><td>Pode-se escrever biografias para personagens chave como &quot;Xuan Hengzi&quot;, &quot;Gongshengzi&quot;, &quot;Lixiangong&quot;, &quot;Sanbaishi&quot;</td></tr><tr><td>E30</td><td>Análise hipotética de pontos de virada históricos</td><td>Analisar como o desenvolvimento da civilização de simbiose seria diferente se um evento histórico tivesse seguido um caminho diferente</td><td>Documento 70-79</td><td>Pode-se fazer análises hipotéticas como &quot;se a constituição de simbiose não tivesse sido aprovada&quot;, &quot;se a estratégia de ativação de 20% tivesse falhado&quot;, mostrando a contingência da história</td></tr><tr><td>E31</td><td>Registros detalhados de descobertas arqueológicas</td><td>Configurar as descobertas detalhadas e resultados de pesquisa de uma arqueologia inter-planar</td><td>Documento 84-87</td><td>Pode-se configurar como &quot;descoberta arqueológica de uma civilização perdida&quot;, &quot;resultados arqueológicos de retrocesso temporal de um nó histórico chave&quot;</td></tr></tbody></table><h2 id="_9-direcoes-de-expansao-inter-planar-e-temporal" tabindex="-1">9. Direções de Expansão Inter-Planar e Temporal <a class="header-anchor" href="#_9-direcoes-de-expansao-inter-planar-e-temporal" aria-label="Permalink to &quot;9. Direções de Expansão Inter-Planar e Temporal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Direção de Expansão</th><th>Valor da Expansão</th><th>Configuração Relacionada</th><th>Sugestão Criativa</th></tr></thead><tbody><tr><td>E32</td><td>Configuração detalhada de um plano específico</td><td>Configurar os parâmetros de leis, forma de civilização, ambiente geográfico e história de um plano específico</td><td>Documento 80, Documento 81</td><td>Pode-se configurar diferentes tipos de planos específicos como &quot;plano de alta magia&quot;, &quot;plano tecnológico&quot;, &quot;plano selvagem&quot;, &quot;plano consciente&quot;</td></tr><tr><td>E33</td><td>Casos de diplomacia inter-planar</td><td>Configurar casos específicos de estabelecimento de relações diplomáticas entre a civilização de simbiose e outras civilizações planares</td><td>Documento 81, Documento 88</td><td>Pode-se configurar eventos diplomáticos específicos como primeiro contato, negociações de estabelecimento de relações, intercâmbios culturais, acordos comerciais</td></tr><tr><td>E34</td><td>Casos específicos de retrocesso temporal</td><td>Configurar o processo específico, descobertas e impactos de uma operação de retrocesso temporal</td><td>Documento 82-83, Documento 89</td><td>Pode-se configurar casos como &quot;resolução por retrocesso de um mistério histórico&quot;, &quot;restauração por retrocesso de uma civilização extinta&quot;</td></tr><tr><td>E35</td><td>Registros detalhados de eventos de paradoxo temporal</td><td>Configurar todo o processo de ocorrência, resposta de emergência e reparo causal de um evento de paradoxo temporal</td><td>Documento 89</td><td>Pode-se escrever um registro completo de tratamento de um evento de paradoxo em pequena escala, mostrando a operação prática do mecanismo de prevenção e controle</td></tr><tr><td>E36</td><td>Conflitos e resoluções inter-planares</td><td>Configurar os conflitos entre a civilização de simbiose e outras civilizações planares e seus processos de resolução pacífica</td><td>Documento 81, Documento 88</td><td>Pode-se configurar diferentes tipos de casos de conflito inter-planar como disputas de recursos, conflitos culturais, disputas fronteiriças</td></tr></tbody></table><h2 id="_10-principios-criativos-para-configuracoes-expansivas" tabindex="-1">10. Princípios Criativos para Configurações Expansivas <a class="header-anchor" href="#_10-principios-criativos-para-configuracoes-expansivas" aria-label="Permalink to &quot;10. Princípios Criativos para Configurações Expansivas&quot;">​</a></h2><p>Ao realizar a criação de configurações expansivas, devem ser seguidos os seguintes princípios:</p><ol><li><strong>Consistência优先</strong>: Todas as configurações expansivas devem manter consistência lógica com as configurações existentes e passar pela verificação da tabela de autoverificação de contradições de configurações.</li><li><strong>Baseado na realidade</strong>: As configurações expansivas devem ser baseadas em leis objetivas para dedução razoável, evitando fantasia pura e colapso de configurações.</li><li><strong>Posição de simbiose</strong>: As configurações expansivas devem sempre manter a posição central de anti-saque e advogar simbiose, não devendo defender comportamentos de saque.</li><li><strong>Abertura</strong>: As configurações expansivas devem manter um certo grau de abertura, reservando espaço para expansões futuras adicionais.</li><li><strong>Praticidade</strong>: As configurações expansivas devem ter valor criativo prático, capazes de fornecer material útil para criação de histórias, design de jogos e discussões teóricas.</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A Lista de Sugestões de Expansão de Configurações é a &quot;porta aberta&quot; do sistema de configurações da Civilização de Simbiose de Âncora. Ela indica que este sistema de configurações não é um produto fechado e completo, mas sim um sistema vivo que cresce continuamente e se enriquece constantemente. As trinta e seis direções de expansão são apenas o ponto de partida; a verdadeira criatividade de configurações vem da imaginação e entusiasmo de cada participante. Desde que os princípios básicos de consistência de configurações sejam seguidos, cada expansão valiosa se tornará uma parte indispensável da grande narrativa da Civilização de Simbiose de Âncora.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>97-Tabela de Autoverificação de Contradições de Configurações</li><li>99-Instruções de Versão e Manutenção de Documentos</li><li>96-Perguntas Frequentes FAQ</li></ul>',27)])])}const h=a(s,[["render",i]]);export{p as __pageData,h as default};
